alter table public.profiles enable row level security;alter table public.interests enable row level security;alter table public.profile_interests enable row level security;alter table public.profile_goals enable row level security;alter table public.privacy_settings enable row level security;alter table public.user_locations_private enable row level security;alter table public.user_presence enable row level security;alter table public.blocks enable row level security;alter table public.connection_requests enable row level security;alter table public.connections enable row level security;alter table public.conversations enable row level security;alter table public.conversation_members enable row level security;alter table public.messages enable row level security;alter table public.message_reactions enable row level security;alter table public.calls enable row level security;alter table public.activities enable row level security;alter table public.activity_members enable row level security;alter table public.activity_invites enable row level security;alter table public.sos_requests enable row level security;alter table public.sos_responses enable row level security;alter table public.help_skills enable row level security;alter table public.profile_help_skills enable row level security;alter table public.reviews enable row level security;alter table public.trust_metrics enable row level security;alter table public.notifications enable row level security;alter table public.reports enable row level security;alter table public.trusted_contacts enable row level security;alter table public.guardian_links enable row level security;alter table public.meeting_sessions enable row level security;alter table public.meeting_participants enable row level security;alter table public.meeting_verifications enable row level security;alter table public.meeting_checkins enable row level security;alter table public.guardian_share_sessions enable row level security;alter table public.security_events enable row level security;

create policy "profiles_select" on public.profiles for select to authenticated using(id=auth.uid() or public.can_socially_interact(auth.uid(),id));
create policy "profiles_update_own" on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy "interests_authenticated_read" on public.interests for select to authenticated using(true);
create policy "profile_interests_read" on public.profile_interests for select to authenticated using(user_id=auth.uid() or public.can_socially_interact(auth.uid(),user_id));
create policy "profile_interests_insert_own" on public.profile_interests for insert to authenticated with check(user_id=auth.uid());
create policy "profile_interests_delete_own" on public.profile_interests for delete to authenticated using(user_id=auth.uid());
create policy "profile_goals_read" on public.profile_goals for select to authenticated using(user_id=auth.uid() or public.can_socially_interact(auth.uid(),user_id));
create policy "profile_goals_insert_own" on public.profile_goals for insert to authenticated with check(user_id=auth.uid());
create policy "profile_goals_delete_own" on public.profile_goals for delete to authenticated using(user_id=auth.uid());
create policy "privacy_select_own" on public.privacy_settings for select to authenticated using(user_id=auth.uid());
create policy "privacy_update_own" on public.privacy_settings for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "private_location_select_own" on public.user_locations_private for select to authenticated using(user_id=auth.uid());
create policy "presence_read_allowed" on public.user_presence for select to authenticated using(user_id=auth.uid() or(visible=true and public.can_socially_interact(auth.uid(),user_id)));
create policy "blocks_select_own" on public.blocks for select to authenticated using(blocker_id=auth.uid() or blocked_id=auth.uid());
create policy "blocks_insert_own" on public.blocks for insert to authenticated with check(blocker_id=auth.uid());
create policy "blocks_delete_own" on public.blocks for delete to authenticated using(blocker_id=auth.uid());
create policy "connection_requests_participants_read" on public.connection_requests for select to authenticated using(sender_id=auth.uid() or receiver_id=auth.uid());
create policy "connections_participants_read" on public.connections for select to authenticated using(user_a=auth.uid() or user_b=auth.uid());
create policy "conversations_members_read" on public.conversations for select to authenticated using(public.is_conversation_member(id,auth.uid()));
create policy "conversation_members_members_read" on public.conversation_members for select to authenticated using(public.is_conversation_member(conversation_id,auth.uid()));
create policy "messages_members_read" on public.messages for select to authenticated using(public.is_conversation_member(conversation_id,auth.uid()));
create policy "messages_send_members" on public.messages for insert to authenticated with check(sender_id=auth.uid() and public.is_conversation_member(conversation_id,auth.uid()));
create policy "message_reactions_members_read" on public.message_reactions for select to authenticated using(exists(select 1 from public.messages m where m.id=message_id and public.is_conversation_member(m.conversation_id,auth.uid())));
create policy "calls_members_read" on public.calls for select to authenticated using(public.is_conversation_member(conversation_id,auth.uid()));
create policy "activities_read_allowed" on public.activities for select to authenticated using(creator_id=auth.uid() or(public.can_socially_interact(auth.uid(),creator_id) and(visibility='public' or(visibility='connections' and public.are_connected(auth.uid(),creator_id))or exists(select 1 from public.activity_invites ai where ai.activity_id=id and ai.receiver_id=auth.uid()))));
create policy "activities_creator_update" on public.activities for update to authenticated using(creator_id=auth.uid()) with check(creator_id=auth.uid());
create policy "activity_members_read_allowed" on public.activity_members for select to authenticated using(user_id=auth.uid() or exists(select 1 from public.activity_members mine where mine.activity_id=activity_id and mine.user_id=auth.uid() and mine.status='confirmed'));
create policy "activity_invites_participants_read" on public.activity_invites for select to authenticated using(sender_id=auth.uid() or receiver_id=auth.uid());
create policy "sos_read_allowed" on public.sos_requests for select to authenticated using(author_id=auth.uid() or public.can_socially_interact(auth.uid(),author_id));
create policy "sos_responses_participants_read" on public.sos_responses for select to authenticated using(helper_id=auth.uid() or exists(select 1 from public.sos_requests s where s.id=sos_id and s.author_id=auth.uid()));
create policy "help_skills_read" on public.help_skills for select to authenticated using(true);
create policy "profile_help_skills_read" on public.profile_help_skills for select to authenticated using(user_id=auth.uid() or public.can_socially_interact(auth.uid(),user_id));
create policy "profile_help_skills_insert_own" on public.profile_help_skills for insert to authenticated with check(user_id=auth.uid());
create policy "profile_help_skills_delete_own" on public.profile_help_skills for delete to authenticated using(user_id=auth.uid());
create policy "reviews_reviewer_read" on public.reviews for select to authenticated using(reviewer_id=auth.uid());
create policy "reviews_reviewer_insert" on public.reviews for insert to authenticated with check(reviewer_id=auth.uid() and public.can_socially_interact(auth.uid(),reviewed_user_id));
create policy "trust_metrics_read_allowed" on public.trust_metrics for select to authenticated using(user_id=auth.uid() or public.can_socially_interact(auth.uid(),user_id));
create policy "notifications_own_read" on public.notifications for select to authenticated using(user_id=auth.uid());
create policy "reports_reporter_read" on public.reports for select to authenticated using(reporter_id=auth.uid());
create policy "trusted_contacts_own" on public.trusted_contacts for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "guardian_links_participant_read" on public.guardian_links for select to authenticated using(minor_user_id=auth.uid() or guardian_user_id=auth.uid());
create policy "meeting_sessions_participants_read" on public.meeting_sessions for select to authenticated using(creator_id=auth.uid() or public.is_meeting_participant(id,auth.uid()));
create policy "meeting_participants_read" on public.meeting_participants for select to authenticated using(public.is_meeting_participant(meeting_id,auth.uid()));
create policy "meeting_verifications_own_read" on public.meeting_verifications for select to authenticated using(user_id=auth.uid());
create policy "meeting_checkins_participants_read" on public.meeting_checkins for select to authenticated using(public.is_meeting_participant(meeting_id,auth.uid()));
create policy "guardian_share_sessions_minor_read" on public.guardian_share_sessions for select to authenticated using(minor_user_id=auth.uid());
create policy "security_events_own_read" on public.security_events for select to authenticated using(user_id=auth.uid());
